import{Z as t,e as o,f as i,a0 as n}from"./chunks/framework.DmpHOl9T.js";const m=JSON.parse('{"title":"Discord","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/messaging/discord.md","filePath":"integrations/messaging/discord.md","lastUpdated":1780377007000}'),a={name:"integrations/messaging/discord.md"};function s(r,e,l,h,c,d){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="discord" tabindex="-1">Discord <a class="header-anchor" href="#discord" aria-label="Permalink to &quot;Discord&quot;">​</a></h1><p>Connect Discord to send a message when a visitor completes your form. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Messaging</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Discord</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-create-a-webhook-in-discord" tabindex="-1">Step 2. Create a Webhook in Discord <a class="header-anchor" href="#step-2-create-a-webhook-in-discord" aria-label="Permalink to &quot;Step 2. Create a Webhook in Discord&quot;">​</a></h3><ol><li>Open your Discord server.</li><li>Go to the <strong>Channel Settings</strong> where you want to post messages.</li><li>Click <strong>Integrations</strong> → <strong>Webhooks</strong>.</li><li>Click <strong>New Webhook</strong>, give it a name and select the target channel.</li><li>Copy the <strong>Webhook URL</strong>.</li></ol><h3 id="step-3-form-settings" tabindex="-1">Step 3. Form Settings <a class="header-anchor" href="#step-3-form-settings" aria-label="Permalink to &quot;Step 3. Form Settings&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Set the recipient or channel supported by the integration. Use the variable picker to include the submitted values your team needs in the message.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Check the intended recipient or channel for the test message and verify that its values match the submission.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',11)])])}const p=t(a,[["render",s]]);export{m as __pageData,p as default};
